async function main(ctx) {
  const originalMsg = ctx.input?.body || {};
  const headers = originalMsg.payload?.headers || [];

  let messageId = '';
  let references = '';

  for (const header of headers) {
    if (header.name.toLowerCase() === 'message-id') {
      messageId = header.value;
    }
    if (header.name.toLowerCase() === 'references') {
      references = header.value;
    }
  }

  return {
    messageId: messageId,
    references: references
  };
}

async function main(ctx) {
  const args = ctx.lastOutputOf('__initial__') || {};
  const threadingHeaders = ctx.lastOutputOf('extract_headers') || {};

  // Build email headers
  const lines = [];
  lines.push('To: ' + (args.to || ''));

  if (args.cc) {
    lines.push('Cc: ' + args.cc);
  }
  if (args.bcc) {
    lines.push('Bcc: ' + args.bcc);
  }

  lines.push('Subject: ' + (args.subject || ''));

  // Add threading headers if replying
  if (threadingHeaders.messageId) {
    lines.push('In-Reply-To: ' + threadingHeaders.messageId);

    let refs = threadingHeaders.references || '';
    if (refs && threadingHeaders.messageId) {
      refs = refs + ' ' + threadingHeaders.messageId;
    } else if (threadingHeaders.messageId) {
      refs = threadingHeaders.messageId;
    }
    if (refs) {
      lines.push('References: ' + refs);
    }
  }

  // Content-Type header
  const contentType = args.is_html ? 'text/html; charset=utf-8' : 'text/plain; charset=utf-8';
  lines.push('Content-Type: ' + contentType);
  lines.push('');
  lines.push(args.body || '');

  const rawMessage = lines.join('\r\n');

  // Base64url encode
  const base64 = Buffer.from(rawMessage).toString('base64');
  const base64url = base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

  return {
    raw: base64url
  };
}

